// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // amounts large enough that two accumulations overflow the mutant's balance
        amount = bound(amount, (type(uint256).max / 2) + 1, type(uint256).max);

        // first cycle: deposit then withdraw all
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdrawAll();
        assertEq(address(c).balance, 0);

        // second cycle must also succeed for any admissible input
        vm.prank(actor);
        c.deposit{value: amount}();
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // universal rule: any admissible amount can be deposited and fully withdrawn,
        // leaving the contract's ETH balance at zero; the mutant's runaway `balance`
        // accounting overflows on the second cycle and reverts instead.
        assertTrue(ok && address(c).balance == 0);
    }
}
